contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address newOwner) public payable {
        require(c.owner() == address(this));
        bool ok = c.setOwner(newOwner); if (__ESBMC_reverted()) return;
        assert(ok && c.owner() == newOwner);
    }
    receive() external payable {}
}

